body{margin:0;font-family:"Open Sans","Inter","Segoe UI",Arial,sans-serif;color:var(--appsmith-theme-textColor, #e2e8f0);background:var(--appsmith-theme-surfaceColor, #0f172a);}
.wrap{display:flex;flex-direction:column;height:100%;background:var(--appsmith-theme-surfaceColor, #0f172a);}
.meta{padding:10px 24px 0;color:var(--appsmith-theme-textSecondaryColor, #94a3b8);font-size:13px;text-align:right;}
.scroll{overflow:auto;flex:1;}
.tbl{width:100%;border-collapse:collapse;font-size:14px;}
.tbl th{text-align:left;padding:12px 16px;color:var(--appsmith-theme-textSoftColor, #cbd5e1);font-weight:700;font-size:14px;background:var(--appsmith-theme-surfaceColor, #0f172a);border-bottom:1px solid var(--appsmith-theme-borderColor, #334155);cursor:pointer;user-select:none;white-space:nowrap;position:sticky;top:0;}
.tbl th .sort{display:inline-flex;flex-direction:column;margin-left:6px;line-height:0.7;vertical-align:middle;}
.tbl th .sort span{font-size:10px;color:var(--appsmith-theme-textMutedColor, #64748b);}
.tbl th .sort span.active{color:var(--appsmith-theme-textStrongColor, #ffffff);}
.tbl td{padding:12px 16px;border:0;color:var(--appsmith-theme-textColor, #e2e8f0);white-space:nowrap;}
.tbl tbody tr:nth-child(odd) td{background:var(--appsmith-theme-surfaceAltColor, #1e293b);}
.tbl tbody tr:nth-child(even) td{background:var(--appsmith-theme-surfaceColor, #0f172a);}
.tbl tbody tr:hover td{background:var(--appsmith-theme-surfaceHoverColor, #26344b);}
.idlink{color:var(--appsmith-theme-linkColor, #60a5fa);text-decoration:underline;cursor:pointer;}
.stat{display:inline-flex;align-items:center;}
.dot{width:10px;height:10px;border-radius:50%;display:inline-block;margin-right:8px;}
.chk{color:var(--dark-22c55e, var(--appsmith-theme-successColor, #34d399));font-weight:700;}
.empty{padding:30px;text-align:center;color:var(--appsmith-theme-textMutedColor, #64748b);font-style:italic;}
.pager{display:flex;align-items:center;gap:8px;padding:14px 24px;border-top:1px solid var(--appsmith-theme-borderColor, #334155);background:var(--appsmith-theme-surfaceColor, #0f172a);}
.pbtn{background:transparent;border:none;color:var(--appsmith-theme-textSoftColor, #cbd5e1);cursor:pointer;padding:6px 8px;border-radius:4px;font-size:16px;}
.pbtn:disabled{color:var(--appsmith-theme-textFaintColor, #475569);cursor:not-allowed;}
.pbtn:hover:not(:disabled){background:var(--appsmith-theme-hoverSoftColor, #1e293b);}
.pnum{min-width:30px;text-align:center;background:var(--dark-1e293b, var(--appsmith-theme-primaryColor, #0F1729));color:#ffffff;border-radius:4px;padding:4px 10px;font-weight:600;border:1px solid var(--appsmith-theme-borderColor, #334155);}
.gotolbl{color:var(--appsmith-theme-textSoftColor, #cbd5e1);font-size:14px;}
.goto{width:60px;padding:6px 8px;border:1px solid var(--appsmith-theme-borderColor, #334155);border-radius:4px;font-size:14px;outline:none;background:var(--appsmith-theme-cardColor, #1e293b);color:var(--appsmith-theme-textStrongColor, #ffffff);}
.psize{margin-left:auto;background:var(--appsmith-theme-cardColor, #1e293b);color:var(--appsmith-theme-textStrongColor, #ffffff);border:1px solid var(--appsmith-theme-borderColor, #334155);border-radius:4px;padding:6px 10px;font-size:14px;outline:none;cursor:pointer;}
.skel{padding:18px 24px;color:var(--appsmith-theme-textSecondaryColor, #94a3b8);}

.tbl td.wrapcol{white-space:normal;word-break:break-word;line-height:1.5;}
.tbl th.wrapcol{white-space:nowrap;}

